'use strict';
// Compose the existing health receipt with Windows Forms and the original PS guard.
const fs=require('fs'),path=require('path'),cp=require('child_process');
function read(p){try{return JSON.parse(fs.readFileSync(p,'utf8').replace(/^\uFEFF/,''))}catch{return null}}
function atomic(p,v){const t=p+'.'+process.pid+'.tmp';fs.writeFileSync(t,JSON.stringify(v,null,2));fs.renameSync(t,p)}
function healthy(h){return !!(h&&h.status==='SERVICE_READY_PLUGIN_LINK_NOT_VERIFIED'&&h.local?.ok&&h.public?.ok&&h.local.issuer===h.public.issuer)}
function reason(h){
 if(!h)return '检查结果不可读取，请检查连接服务';
 if(h.status==='STARTUP_PENDING')return '连接服务正在启动';
 if(!h.local?.ok)return '本机连接服务异常，自动恢复仍在继续';
 if(h.public?.status===401||h.public?.status===403)return '公网访问或授权异常，需要核对';
 if(!h.public?.ok)return '公网入口不可达，可能是网络或隧道异常';
 return '连接配置或健康检查异常';
}
function transition(previous,h,ack,now=Date.now()){
 const s=previous||{failures:0,episode:null};
 const age=h?now-Date.parse(h.utc):Infinity;
 if(healthy(h)&&age>=0&&age<300000)return {failures:0,episode:null,last_health_utc:h.utc,mode:'HEALTHY',message:'连接已恢复',threshold:2,sound_interval_ms:5000};
 // A repeated read of the same receipt must not manufacture a second failure.
 if(h?.utc===s.last_health_utc&&age<300000)return {...s,mode:s.episode&&ack?.episode===s.episode?'ACKNOWLEDGED':s.mode};
 const failures=(s.failures||0)+1;
 const episode=s.episode||(failures>=2?new Date(now).toISOString():null);
 const mode=episode?(ack?.episode===episode?'ACKNOWLEDGED':'ALARM'):'PENDING';
 return {failures,episode,last_health_utc:h?.utc||null,mode,message:age>=300000?'连接健康检查已超过5分钟未更新':reason(h),threshold:2,sound_interval_ms:5000,updated_utc:new Date(now).toISOString()};
}
function main(runtime,options={}){
 const dir=path.resolve(runtime);const health=read(path.join(dir,'autostart-health.json'));
 const state=transition(read(path.join(dir,'connection-alert.json')),health,read(path.join(dir,'connection-alert-ack.json')));
 atomic(path.join(dir,'connection-alert.json'),state);
 if(state.mode==='ALARM'&&!options.noLaunch){
  const taskName=options.taskName||'GPT-D-Connection-Alert';
  const run=cp.spawnSync('schtasks.exe',['/Run','/TN',taskName],{encoding:'utf8',windowsHide:true,timeout:8000});
  atomic(path.join(dir,'connection-alert-launch.json'),{utc:new Date().toISOString(),task:taskName,exit_code:run.status,episode:state.episode});
  if(run.status!==0)throw Error('INTERACTIVE_ALERT_TASK_FAILED '+(run.error?.code||run.status));
 }
 console.log(JSON.stringify({mode:state.mode,failures:state.failures,episode:state.episode}));return state;
}
module.exports={transition,healthy,reason,main};
if(require.main===module){try{main(process.argv[2]||'C:/AI/DevSpace-Benchmark-20261031/connector-fixed',{noLaunch:process.argv.includes('--no-launch')})}catch(e){console.error('CONNECTION_ALERT_FAILED '+e.message);process.exitCode=1}}

