'use strict';
// Add one bounded notification call after the original fixed-health publication.
const fs=require('fs'),cp=require('child_process');
const root=process.argv[2]||'C:/AI/DevSpace-Benchmark-20261031';
const file=root+'/ensure-connector.cjs';
const hook=`
// D_CONNECTION_ALERT_V1: notification does not replace health checks or reconnection.
if(fixed)process.on('exit',()=>{try{
 const r=require('child_process').spawnSync(process.execPath,[root+'/connection-alert.cjs',root+'/connector-fixed'],{cwd:root,windowsHide:true,encoding:'utf8',timeout:10000});
 if(r.status!==0)console.error('D_CONNECTION_ALERT_FAILED '+(r.error?.code||r.status));
}catch(e){console.error('D_CONNECTION_ALERT_FAILED '+e.message)}});
`;
const old=fs.readFileSync(file,'utf8');
if(old.includes('D_CONNECTION_ALERT_V1')){console.log('ALREADY_INSTALLED');process.exit(0)}
if(!old.includes("require(fixed?root+'/ensure-connector-fixed.cjs':root+'/ensure-connector.quick-tunnel.cjs');"))throw Error('BASELINE_MISMATCH');
for(const p of ['connection-alert.cjs','Show-ConnectionAlert.ps1','connection-alert-guard/Invoke-GuardedPowerShell.ps1'])if(!fs.existsSync(root+'/'+p))throw Error('MISSING_'+p);
const candidate=file+'.alert-candidate.cjs';fs.writeFileSync(candidate,old+hook);
const check=cp.spawnSync(process.execPath,['--check',candidate],{encoding:'utf8'});
if(check.status!==0)throw Error('SYNTAX_FAILED '+check.stderr);
const backup=file+'.before-alert-'+Date.now();fs.copyFileSync(file,backup);fs.renameSync(candidate,file);
console.log(JSON.stringify({status:'ALERT_HOOK_INSTALLED',backup,original_scheduler_unchanged:true}));

test-connection-alert.cjs:
'use strict';
const assert=require('node:assert/strict');
const {transition}=require('./connection-alert.cjs');
const now=Date.now();
const bad=i=>({utc:new Date(now+i*1000).toISOString(),status:'DEGRADED',local:{ok:true},public:{ok:false}});
let a=transition(null,bad(0),null,now);assert.equal(a.mode,'PENDING');
let b=transition(a,bad(0),null,now+1);assert.equal(b.failures,1);assert.equal(b.mode,'PENDING');
let c=transition(b,bad(1),null,now+1000);assert.equal(c.mode,'ALARM');assert.equal(c.sound_interval_ms,5000);
let d=transition(c,bad(2),{episode:c.episode},now+2000);assert.equal(d.mode,'ACKNOWLEDGED');
const good={utc:new Date(now+3000).toISOString(),status:'SERVICE_READY_PLUGIN_LINK_NOT_VERIFIED',local:{ok:true,issuer:'x'},public:{ok:true,issuer:'x'}};
let e=transition(d,good,null,now+3000);assert.equal(e.mode,'HEALTHY');assert.equal(e.episode,null);
let f=transition(e,bad(4),{episode:c.episode},now+4000);assert.equal(f.mode,'PENDING');
let g=transition(f,bad(5),{episode:c.episode},now+5000);assert.equal(g.mode,'ALARM');assert.notEqual(g.episode,c.episode);
let stale=transition(e,good,null,now+400000);assert.equal(stale.mode,'PENDING');assert.match(stale.message,/5分钟/);
let malformed=transition(null,{...good,utc:'invalid'},null,now);malformed=transition(malformed,{...good,utc:'invalid'},null,now+120000);assert.equal(malformed.mode,'ALARM');
console.log('PASS: debounce, duplicate receipt, persistent alarm, acknowledgement, recovery, new episode, stale health');
